    const items = $input.all();

    if (items.length === 0) {
        return "<i>📭 No devices yet.</i>";
    }

    let msg = "<pre>\n";
    msg += "No | IP Address      | Brand\n";
    msg += "---------------------------------\n";

    items.forEach(item => {
        const d = item.json;

        const no = String(d.id).padEnd(3, ' ');
        const ip = String(d.address).padEnd(15, ' ');
        const brand = String(d.brand);

        msg += `${no}| ${ip} | ${brand}\n`;
    });

    msg += "</pre>";

    return msg;
  })()
}}
