const text = $input.item.json.message.text.trim();
const args = text.split(/\s+/);

if (args.length === 1) {
    return { json: { route: "show_list" } };
}

const idInput = parseInt(args[1], 10);

if (isNaN(idInput) || idInput <= 0) {
    return { json: { 
        route: "error", 
        pesan_error: "❌ <b>Invalid Format!</b>\n\nDevice ID must be a valid number.\nExample: <code>/remove 1</code>" 
    }};
}

return { json: { 
        route: "delete", 
        id: idInput 
}};

const text = $input.item.json.message.text.trim();
const args = text.split(/\s+/);

if (args.length !== 7) {
    return { json: { 
        is_valid: false, 
        pesan_error: "❌ <b>Invalid Format!</b>\n\nPlease use this format:\n<code>/add (address) (ssh port) (username) (password) (brand) (ftp port)</code>" 
    }};
}

const brandInput = args[5].toLowerCase();
const validBrands = ['mikrotik', 'cisco', 'huawei', 'juniper'];

if (!validBrands.includes(brandInput)) {
    return { json: { 
        is_valid: false, 
        pesan_error: "❌ <b>Unsupported Brand!</b>\n\nAllowed brands are only: <i>mikrotik, cisco, huawei, juniper</i>." 
    }};
}

return { json: {
    is_valid: true,
    address: args[1],
    port: args[2],
    username: args[3],
    password: args[4],
    brand: brandInput,
    portftp: args[6]
}};

